import java.io.*;
import java.util.*;

public class Task7 {
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;
        FastScanner(InputStream f) { br = new BufferedReader(new InputStreamReader(f)); }
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try { st = new StringTokenizer(br.readLine()); } catch (IOException e) {}
            }
            return st.nextToken();
        }
        int nextInt() { return Integer.parseInt(next()); }
    }

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        int n = in.nextInt();
        int B = in.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = in.nextInt();
        int[] costs = new int[n];
        int countCosts = 0;
        int even = 0, odd = 0;
        for (int i = 0; i < n; i++) {
            if (a[i] % 2 == 0) even++;
            else odd++;
            if (even == odd && i != n - 1) costs[countCosts++] = Math.abs(a[i] - a[i+1]);
        }
        Arrays.sort(costs, 0, countCosts);
        int ans = 0;
        for (int j = 0; j < countCosts && B >= costs[j]; j++) {
            ans++;
            B -= costs[j];
        }
        System.out.println(ans);
    }
}
